<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Criar conta | EcoENEM</title><link rel="icon" href="../imgs/ecoenemicon.png"><link rel="stylesheet" href="../css/auth.css"></head><body><main class="auth-wrap"><section class="auth-card glass"><a class="auth-logo" href="../index.php">EcoENEM</a><h1>Crie sua conta</h1><p class="auth-subtitle">Seu espaço de estudos começa aqui.</p><form id="cadastroForm"><label for="nome">Nome</label><input id="nome" maxlength="60" autocomplete="given-name" required><label for="sobrenome">Sobrenome</label><input id="sobrenome" maxlength="80" autocomplete="family-name" required><label for="email">E-mail</label><input id="email" type="email" autocomplete="email" required><label for="senha">Senha</label><div class="password-field"><input id="senha" type="password" autocomplete="new-password" required><button type="button" class="toggle-password" data-target="senha">◉</button></div><ul class="password-rules"><li data-rule="length">8 caracteres ou mais</li><li data-rule="upper">Uma letra maiúscula</li><li data-rule="lower">Uma letra minúscula</li><li data-rule="number">Um número</li><li data-rule="special">Um caractere especial</li></ul><label for="confirmar">Confirmar senha</label><div class="password-field"><input id="confirmar" type="password" autocomplete="new-password" required><button type="button" class="toggle-password" data-target="confirmar">◉</button></div><p id="mensagem" class="auth-message" role="alert"></p><button class="auth-submit" id="criar" type="submit" disabled>Criar conta</button></form><p class="auth-foot">Já tem uma conta? <a href="login.php">Voltar para o login</a></p></section></main><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script><script src="../js/auth.js"></script><script>
const nomeCampo=document.getElementById('nome'), sobrenomeCampo=document.getElementById('sobrenome'), emailCampo=document.getElementById('email'), senhaCampo=document.getElementById('senha'), confirmarCampo=document.getElementById('confirmar');const campos=[nomeCampo,sobrenomeCampo,emailCampo,senhaCampo,confirmarCampo], btn=document.getElementById('criar'), msg=document.getElementById('mensagem');
function validar(){const s=senhaCampo.value;const regras={length:s.length>=8,upper:/[A-Z]/.test(s),lower:/[a-z]/.test(s),number:/\d/.test(s),special:/[^A-Za-z0-9]/.test(s)};document.querySelectorAll('[data-rule]').forEach(li=>{li.classList.toggle('valid',regras[li.dataset.rule]);li.textContent=(regras[li.dataset.rule]?'✓ ':'○ ')+({length:'8 caracteres ou mais',upper:'Uma letra maiúscula',lower:'Uma letra minúscula',number:'Um número',special:'Um caractere especial'}[li.dataset.rule]);});const emailOk=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailCampo.value);btn.disabled=!(nomeCampo.value.trim()&&sobrenomeCampo.value.trim()&&emailOk&&Object.values(regras).every(Boolean)&&confirmarCampo.value===s&&s.length>0);}
campos.forEach(c=>c.addEventListener('input',validar));
document.getElementById('cadastroForm').addEventListener('submit',async e=>{e.preventDefault();validar();if(btn.disabled)return;btn.disabled=true;btn.textContent='Criando...';msg.textContent='';try{const {data,error}=await EcoAuth.client.auth.signUp({email:emailCampo.value.trim(),password:senhaCampo.value,user_metadata:{nome:nomeCampo.value.trim(),sobrenome:sobrenomeCampo.value.trim()}});if(error)throw error;if(data.session){await EcoAuth.sync(data.session);await EcoAuth.registrarAcesso();location.href='../index.php';}else{msg.textContent='Conta criada! Verifique seu e-mail para confirmar o cadastro e depois entre.';msg.classList.add('success');}}catch(err){msg.textContent=EcoAuth.mensagemErro(err);}finally{btn.textContent='Criar conta';validar();}});
</script></body></html>
